import { Handle, Position } from 'reactflow';

const NODE_WIDTH = 220;

const HandleLabel = ({ label, side }) => (
  <span
    className={`
      absolute
      ${side === 'left' ? 'left-4' : 'right-4'}
      text-[10px]
      font-medium
      text-slate-500
      whitespace-nowrap
      pointer-events-none
      select-none
    `}
  >
    {label}
  </span>
);

export const NodeTextField = ({ label, value, onChange, placeholder }) => (
  <label className="flex flex-col gap-1">
    <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
      {label}
    </span>
    <input
      type="text"
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      className="
        w-full
        rounded-lg
        border border-slate-300
        bg-slate-50
        px-3 py-2
        text-sm
        transition-all duration-200
        focus:border-indigo-500
        focus:ring-2
        focus:ring-indigo-200
        focus:outline-none
      "
    />
  </label>
);

export const NodeTextArea = ({
  label,
  value,
  onChange,
  placeholder,
  rows = 3,
}) => (
  <label className="flex flex-col gap-1">
    <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
      {label}
    </span>
    <textarea
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      rows={rows}
      className="
        w-full
        rounded-lg
        border border-slate-300
        bg-slate-50
        px-3 py-2
        text-sm
        resize-y
        min-h-[80px]
        transition-all duration-200
        focus:border-indigo-500
        focus:ring-2
        focus:ring-indigo-200
        focus:outline-none
      "
    />
  </label>
);

export const NodeSelect = ({ label, value, onChange, options }) => (
  <label className="flex flex-col gap-1">
    <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
      {label}
    </span>
    <select
      value={value}
      onChange={onChange}
      className="
        w-full
        rounded-lg
        border border-slate-300
        bg-slate-50
        px-3 py-2
        text-sm
        transition-all duration-200
        focus:border-indigo-500
        focus:ring-2
        focus:ring-indigo-200
        focus:outline-none
      "
    >
      {options.map(({ value: v, label: l }) => (
        <option key={v} value={v}>
          {l}
        </option>
      ))}
    </select>
  </label>
);

export const NodeNumberField = ({
  label,
  value,
  onChange,
  min,
  max,
  step,
}) => (
  <label className="flex flex-col gap-1">
    <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
      {label}
    </span>
    <input
      type="number"
      value={value}
      onChange={onChange}
      min={min}
      max={max}
      step={step}
      className="
        w-full
        rounded-lg
        border border-slate-300
        bg-slate-50
        px-3 py-2
        text-sm
        transition-all duration-200
        focus:border-indigo-500
        focus:ring-2
        focus:ring-indigo-200
        focus:outline-none
      "
    />
  </label>
);

export const NodeToggle = ({ label, checked, onChange }) => (
  <label className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer">
    <input
      type="checkbox"
      checked={checked}
      onChange={onChange}
      className="h-4 w-4 accent-indigo-600"
    />
    <span>{label}</span>
  </label>
);

const handleTop = (index, total, override) => {
  if (override !== undefined) return `${override * 100}%`;

  if (total === 1) return '50%';

  const step = 60 / (total - 1);
  return `${20 + step * index}%`;
};

export const BaseNode = ({
  id,
  label,
  color = '#4f46e5',
  icon,
  inputs = [],
  outputs = [],
  minHeight = 60,
  children,
}) => {
  return (
    <div
      className="
        relative
        overflow-visible
        rounded-2xl
        border border-slate-200
        bg-white
        shadow-lg
        hover:shadow-2xl
        hover:-translate-y-1
        transition-all duration-300
      "
      style={{ width: NODE_WIDTH }}
    >
      {/* Header */}
      <div
        className="
          flex items-center gap-2
          px-4 py-3
          rounded-t-2xl
          text-white
          text-sm
          font-semibold
          tracking-wide
        "
        style={{
          background: `linear-gradient(135deg, ${color}, #8b5cf6)`,
        }}
      >
        {icon && <span className="text-base">{icon}</span>}
        <span>{label}</span>
      </div>

      {/* Body */}
      <div
        className="
          p-4
          flex flex-col
          gap-3
          bg-white
          rounded-b-2xl
        "
        style={{ minHeight }}
      >
        {children}
      </div>

      {inputs.map((h, i) => (
        <div
          key={h.id}
          className="absolute left-0 flex items-center -translate-y-1/2"
          style={{ top: handleTop(i, inputs.length, h.position) }}
        >
          <Handle
            type="target"
            position={Position.Left}
            id={`${id}-${h.id}`}
            className="
              !w-3 !h-3
              !border-2 !border-white
              !shadow-md
              hover:!scale-125
              transition-all
            "
            style={{
              background: color,
              left: -6,
            }}
          />
          <HandleLabel label={h.label} side="left" />
        </div>
      ))}

      {outputs.map((h, i) => (
        <div
          key={h.id}
          className="absolute right-0 flex items-center -translate-y-1/2"
          style={{ top: handleTop(i, outputs.length, h.position) }}
        >
          <Handle
            type="source"
            position={Position.Right}
            id={`${id}-${h.id}`}
            className="
              !w-3 !h-3
              !border-2 !border-white
              !shadow-md
              hover:!scale-125
              transition-all
            "
            style={{
              background: color,
              right: -6,
            }}
          />
          <HandleLabel label={h.label} side="right" />
        </div>
      ))}
    </div>
  );
};
